    "maps.calculate_route": { en: "Calculate route", it: "Calcola percorso", de: "Route berechnen", fr: "Calculer l’itinéraire", es: "Calcular ruta", pt: "Calcular rota", nl: "Route berekenen", sv: "Beräkna rutt", pl: "Oblicz trasę", id: "Hitung rute", zh: "计算路线", ja: "ルートを計算", ko: "경로 계산", hi: "मार्ग गणना", ru: "Рассчитать маршрут", ckb: "ڕێگا حیساب بکە", kmr: "Rê hesab bike", tr: "Rotayı hesapla", ar: "احسب المسار", fa: "محاسبه مسیر", ur: "راستہ حساب کریں" },
    "maps.clear_plan": { en: "Clear plan", it: "Cancella piano", de: "Plan löschen", fr: "Effacer le plan", es: "Borrar plan", pt: "Limpar plano", nl: "Plan wissen", sv: "Rensa plan", pl: "Wyczyść plan", id: "Hapus rencana", zh: "清除计划", ja: "計画を消去", ko: "계획 지우기", hi: "योजना साफ़ करें", ru: "Очистить план", ckb: "پلان پاک بکە", kmr: "Planê paqij bike", tr: "Planı temizle", ar: "مسح الخطة", fa: "پاک کردن برنامه", ur: "منصوبہ صاف کریں" },
    "maps.copy_share": { en: "Copy share text", it: "Copia testo da condividere", de: "Freigabetext kopieren", fr: "Copier le texte de partage", es: "Copiar texto para compartir", pt: "Copiar texto de partilha", nl: "Deeltekst kopiëren", sv: "Kopiera delningstext", pl: "Kopiuj tekst udostępniania", id: "Salin teks berbagi", zh: "复制分享文本", ja: "共有テキストをコピー", ko: "공유 텍스트 복사", hi: "साझा पाठ कॉपी करें", ru: "Копировать текст для отправки", ckb: "دەقی هاوبەشکردن کۆپی بکە", kmr: "Nivîsa parvekirinê kopî bike", tr: "Paylaşım metnini kopyala", ar: "نسخ نص المشاركة", fa: "کپی متن اشتراک", ur: "شیئر متن کاپی کریں" },
